 const{currentOrganization,hasPermission,isLoading}=useOrganization();const org=currentOrganization?.organization_id;const fetch=useServerFn(queryPartners);const act=useServerFn(actOnShipment);const receive=useServerFn(receivePartnerReturn);const cache=useQueryClient();const[confirm,setConfirm]=useState<"approve"|"start_picking"|"ship"|"receive"|"cancel"|null>(null);const[receiver,setReceiver]=useState("");const[returned,setReturned]=useState(false);const[drafts,setDrafts]=useState<Record<string,string>>({});const permission=kind==="shipment"?"partner_shipments.read":"partner_returns.read";
